package com.masterclass.inventory.service; import com.masterclass.inventory.dto.SaleDtos.*; import com.masterclass.inventory.entity.*; import com.masterclass.inventory.exception.*; import com.masterclass.inventory.mapper.SaleMapper; import com.masterclass.inventory.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.*;
@Service @RequiredArgsConstructor public class SaleService { private final ProductRepository products; private final SaleRepository sales; private final InventoryMovementRepository movements; private final SaleMapper mapper; @Transactional public SaleResponse create(SaleRequest req){ Sale sale=Sale.builder().saleDate(OffsetDateTime.now()).totalAmount(BigDecimal.ZERO).build(); BigDecimal total=BigDecimal.ZERO; for(var item:req.items()){ Product p=products.findById(item.productId()).orElseThrow(()->new NotFoundException("Product not found: "+item.productId())); if(p.getStatus()!=ProductStatus.ACTIVE) throw new BusinessException("Product is not active: "+p.getSku()); if(p.getCurrentStock()<item.quantity()) throw new BusinessException("Insufficient stock for SKU "+p.getSku()); p.decreaseStock(item.quantity()); BigDecimal subtotal=p.getUnitPrice().multiply(BigDecimal.valueOf(item.quantity())); sale.addDetail(SaleDetail.builder().product(p).quantity(item.quantity()).unitPrice(p.getUnitPrice()).subtotal(subtotal).build()); total=total.add(subtotal); movements.save(InventoryMovement.builder().product(p).movementType(MovementType.SALE).quantity(item.quantity()).date(OffsetDateTime.now()).user("pos-terminal").build()); } sale.setTotalAmount(total); return mapper.toResponse(sales.save(sale)); } @Transactional(readOnly=true) public List<SaleResponse> list(){return sales.findAll().stream().map(mapper::toResponse).toList();} @Transactional(readOnly=true) public SaleResponse get(Long id){return mapper.toResponse(sales.findById(id).orElseThrow(()->new NotFoundException("Sale not found")));} }
